#include "InjectorTester.h"
namespace injector_diagnostic {InjectorTestResult InjectorTester::run(InjectorTestType t)const{switch(t){case InjectorTestType::Resistance:return{t,true,12.4,"ohm","Simulated resistance is within example range.",true};case InjectorTestType::Pulse:return{t,true,3.0,"ms","Simulated pulse command accepted.",true};case InjectorTestType::Flow:return{t,true,105.0,"mL/min","Simulated flow result.",true};case InjectorTestType::Leak:return{t,true,0.0,"mL/min","Simulated leak test: no leak detected.",true};}return{t,false,0.0,"","Unknown test.",true};}std::string InjectorTester::testName(InjectorTestType t){switch(t){case InjectorTestType::Resistance:return "Resistance";case InjectorTestType::Pulse:return "Pulse Test";case InjectorTestType::Flow:return "Flow Test";case InjectorTestType::Leak:return "Leak Test";}return "Unknown";}}
